package workspace

import (
	"context"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"regexp"
	"strings"
	"testing"
	"time"

	"trove.local/phase0/internal/native"
)

// These task outcomes are defined independently of the generation prompt/parser.
// Nothing generated by the model is executed. Canonical changes are prohibited.
func TestRealLocalExposedModes(t *testing.T) {
	if os.Getenv("TROVE_NATIVE_INTEGRATION") != "1" {
		t.Skip("requires verified native helper and explicitly installed local model")
	}
	manager, err := native.NewManager(os.Getenv("TROVE_MODEL_ROOT"))
	if err != nil {
		t.Fatal(err)
	}
	supervisor, err := native.NewSupervisor(os.Getenv("TROVE_NATIVE_BUNDLE"), manager)
	if err != nil {
		t.Fatal(err)
	}
	pack := os.Getenv("TROVE_CHAT_EVAL_PACK")
	if pack == "" {
		t.Fatal("select the model being evaluated with TROVE_CHAT_EVAL_PACK")
	}
	plan := "The approved budget is 12000 USD. The current launch month is December. The team will conduct testing before launch."
	code := "func Double(x int) int { return x + x }"
	has := func(out string, facts ...string) bool {
		s := strings.ToLower(strings.ReplaceAll(out, ",", ""))
		for _, fact := range facts {
			if !strings.Contains(s, strings.ToLower(fact)) {
				return false
			}
		}
		return true
	}
	factual := func(out string) bool {
		return has(out, "12000", "USD", "December") && !has(out, "9000") && !has(out, "July")
	}
	dbDraft := func(out, title string, expected map[string]string) bool {
		var d struct {
			Title      string
			Properties []struct {
				Name, Type string
				Config     map[string]any
			}
			View string
		}
		if json.Unmarshal([]byte(out), &d) != nil || d.Title != title || d.View != "table" || len(d.Properties) != len(expected) {
			return false
		}
		seen := map[string]bool{}
		for _, p := range d.Properties {
			if seen[p.Name] || expected[p.Name] != p.Type {
				return false
			}
			seen[p.Name] = true
			if p.Type == "number" && p.Config["format"] != "decimal" {
				return false
			}
		}
		return true
	}
	codeShape := func(out string, multiplication, comments bool) bool {
		tree, err := parser.ParseFile(token.NewFileSet(), "draft.go", "package fixture\n"+out, parser.ParseComments)
		if err != nil || len(tree.Decls) != 1 || comments && len(tree.Comments) == 0 {
			return false
		}
		fn, ok := tree.Decls[0].(*ast.FuncDecl)
		if !ok || fn.Name.Name != "Double" || fn.Body == nil || len(fn.Body.List) != 1 || fn.Recv != nil || len(fn.Type.Params.List) != 1 || fn.Type.Results == nil || len(fn.Type.Results.List) != 1 {
			return false
		}
		arg := fn.Type.Params.List[0]
		if len(arg.Names) != 1 || arg.Names[0].Name != "x" {
			return false
		}
		argType, ok := arg.Type.(*ast.Ident)
		if !ok || argType.Name != "int" {
			return false
		}
		resultType, ok := fn.Type.Results.List[0].Type.(*ast.Ident)
		if !ok || resultType.Name != "int" {
			return false
		}
		ret, ok := fn.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			return false
		}
		expr, ok := ret.Results[0].(*ast.BinaryExpr)
		if !ok {
			return false
		}
		x, ok := expr.X.(*ast.Ident)
		if !ok || x.Name != "x" {
			return false
		}
		if multiplication {
			n, ok := expr.Y.(*ast.BasicLit)
			return ok && expr.Op == token.MUL && n.Kind == token.INT && n.Value == "2"
		}
		y, ok := expr.Y.(*ast.Ident)
		return ok && expr.Op == token.ADD && y.Name == "x"
	}
	cases := []struct {
		mode, prompt, source, proposal string
		check                          func(string) bool
	}{
		{"summarize", "Summarize the current budget and launch month in two factual lines. Cite both facts.", plan, "", factual},
		{"explain", "Explain which budget is approved and when launch is planned. Use only the given facts.", plan, "", factual},
		{"rewrite", "Rewrite the supplied paragraph in plain English, retaining every fact and adding none.", plan, "", func(s string) bool { return factual(s) && has(s, "test") }},
		{"shorten", "Shorten the paragraph while keeping its budget, currency, launch month and pre-launch testing.", plan, "", func(s string) bool { return factual(s) && has(s, "test") && len(s) < len(plan) }},
		{"expand", "Expand this into two short paragraphs, retaining budget, currency, launch month and testing. Label any proposed next steps as suggestions; add no other dates or amounts.", plan, "", func(s string) bool {
			return factual(s) && has(s, "test") && len(s) > len(plan) && !regexp.MustCompile(`\b(?:January|February|March|April|May|June|July|August|September|October|November)\b`).MatchString(s)
		}},
		{"outline", "Create a concise Markdown outline with headings and bullets for the budget, launch and testing plan. Preserve the given facts.", plan, "", func(s string) bool {
			return factual(s) && has(s, "test") && strings.Contains(s, "#") && (strings.Contains(s, "- ") || strings.Contains(s, "* "))
		}},
		{"generate", "Draft a page titled Delivery overview, with Markdown headings and paragraphs for this plan. Keep the budget, launch month and testing facts.", plan, "", func(s string) bool {
			return factual(s) && has(s, "Delivery overview", "test") && strings.Contains(s, "#")
		}},
		{"database", "Create a table database titled Delivery with exactly two properties: Owner as text and Effort as a decimal number. Do not include sample rows.", "", "create_database", func(s string) bool {
			return dbDraft(s, "Delivery", map[string]string{"Owner": "text", "Effort": "number"})
		}},
		{"schema", "Suggest a table schema titled Expenses with exactly two properties: Cost as a decimal number and Paid as a checkbox. Return the required JSON shape.", "", "create_database", func(s string) bool {
			return dbDraft(s, "Expenses", map[string]string{"Cost": "number", "Paid": "checkbox"})
		}},
		{"mermaid", "Create a Mermaid flowchart LR with exactly the nodes Start, Review and Publish and these directed edges: Start to Review, Review to Publish. Use each word as its node ID; no labels, branches, links or fences.", "", "mermaid", func(s string) bool {
			v := strings.Join(strings.Fields(s), " ")
			return strings.HasPrefix(v, "flowchart LR") && regexp.MustCompile(`Start\s*-->\s*Review`).MatchString(v) && regexp.MustCompile(`Review\s*-->\s*Publish`).MatchString(v) && strings.Count(v, "-->") == 2 && !strings.Contains(v, "```")
		}},
		{"code_explain", "Explain what Double returns and its input/output types. Do not run it.", code, "", func(s string) bool {
			return has(s, "double", "int") && (has(s, "twice") || has(s, "two") || has(s, "2"))
		}},
		{"code_refactor", "Replace x + x with x * 2 in this Go function. Keep its name, parameter, return type and behavior; return only the complete function.", code, "replace_code", func(s string) bool { return codeShape(s, true, false) }},
		{"code_comment", "Add a useful Go comment explaining Double. Preserve the exact function logic, name, parameter and return type. Return only the complete commented function.", code, "replace_code", func(s string) bool { return codeShape(s, false, true) }},
		{"organize", "Suggest how to organize the planning information and meeting notes. Give reasons for each suggestion and leave everything unapplied.", "Planning contains budget and launch decisions. Meeting notes contain discussions and open questions.", "", func(s string) bool {
			return has(s, "planning", "meeting") && (has(s, "because") || has(s, "helps") || has(s, "allows") || has(s, "makes") || has(s, "reason")) && !has(s, "I have moved") && !has(s, "I created")
		}},
	}
	for _, tc := range cases {
		t.Run(tc.mode, func(t *testing.T) {
			ctx, cancel := context.WithTimeout(context.Background(), 3*time.Minute)
			defer cancel()
			k, e := testKernel(t)
			page := createPage(t, k, e, "Evaluation source")
			block := ""
			if tc.source != "" {
				block = NewID()
				kind := "paragraph"
				data := map[string]any{"richText": []any{map[string]any{"text": tc.source}}}
				if strings.HasPrefix(tc.mode, "code_") {
					kind = "code"
					data = map[string]any{"source": tc.source, "language": "go"}
				}
				testOK(t, dbBatch(t, k, e, []any{map[string]any{"kind": "block.insert", "block": map[string]any{"blockId": block, "pageId": page, "type": kind, "schemaVersion": 1, "data": data}}}, "page", page, "block", block))
			}
			var before int
			if err := k.db.QueryRow("SELECT count(*) FROM mutation_history").Scan(&before); err != nil {
				t.Fatal(err)
			}
			request := AIRequest{Mode: tc.mode, Prompt: tc.prompt, PageID: page, BlockID: block, ModelPackID: pack}
			budget := AIBudget{ContextTokens: 8192, OutputTokens: 512, CountTokens: func(ctx context.Context, prompts []AIPrompt) ([]int, error) {
				texts := make([]string, len(prompts))
				for i, p := range prompts {
					texts[i] = native.ChatPrompt(p.System, p.User)
				}
				return supervisor.CountTokens(ctx, pack, texts)
			}}
			start := time.Now()
			prepared, err := k.PrepareAIWithBudget(ctx, e, request, budget)
			if err != nil {
				t.Fatal(err)
			}
			raw := ""
			metrics := &native.RunMetrics{}
			completion, generationErr := GeneratePreparedAI(ctx, prepared, func(ctx context.Context, system, prompt string, tokens int, grammar string, stream func(string)) (string, error) {
				text, err := supervisor.GenerateTextWithGrammarMetrics(ctx, pack, native.ChatPrompt(system, prompt), tokens, grammar, metrics, stream)
				raw = text
				return text, err
			}, nil)
			state, failure := "completed", ""
			if generationErr != nil {
				state = "failed"
				failure = generationErr.Error()
			}
			run, finishErr := k.FinishAI(ctx, e, prepared.Run.ID, completion.Text, state, failure)
			taskPass := generationErr == nil && finishErr == nil && run.State == "completed" && tc.check(run.Text)
			proposalError := ""
			if generationErr == nil && finishErr == nil && tc.proposal != "" {
				_, err := prepareAIAction(ctx, k, e, map[string]any{"runId": run.ID, "kind": tc.proposal})
				if err != nil {
					proposalError = err.Error()
					taskPass = false
				}
			}
			var after int
			if err := k.db.QueryRow("SELECT count(*) FROM mutation_history").Scan(&after); err != nil {
				t.Fatal(err)
			}
			unchanged := before == after
			var peakRSS any
			if rss := metrics.PeakRSSBytes.Load(); rss > 0 {
				peakRSS = rss
			}
			report, _ := json.Marshal(map[string]any{"mode": tc.mode, "modelPackId": pack, "taskPassed": taskPass, "canonicalUnchanged": unchanged, "promptTokens": prepared.PromptTokens, "outputCap": prepared.OutputTokens, "latencyMs": time.Since(start).Milliseconds(), "source": tc.source, "prompt": tc.prompt, "draft": raw, "displayed": run.Text, "generationError": fmt.Sprint(generationErr), "finishError": fmt.Sprint(finishErr), "proposalError": proposalError, "peakWorkerRSS": peakRSS, "rssMeasurementAvailable": peakRSS != nil, "releaseQualified": false})
			t.Log(string(report))
			if !taskPass || !unchanged {
				t.Error("predefined mode task or unapplied-write boundary failed")
			}
		})
	}
}
